    "cherwell",
    # ITSM competitors sharing ServiceNow vocabulary (v0.5.0):
    "manageengine",
    "servicedesk plus",
    "sysaid",
    "ivanti",
    "topdesk",
    "halo itsm",
    "haloitsm",
    "solarwinds service desk",
